import { useEffect, useState } from "react";
import { ipc } from "../lib/ipc";
import type { FileEntry } from "../contracts/types";

export function FileExplorer(props: {
  onOpen: (path: string) => void;
  query: string;
  onQuery: (q: string) => void;
}) {
  const [entries, setEntries] = useState<FileEntry[]>([]);
  const [workspaceId, setWorkspaceId] = useState<string | null>(null);

  useEffect(() => {
    void (async () => {
      const ws = await ipc.openWorkspace(".");
      setWorkspaceId(ws.id);
      const list = await ipc.listEntries(ws.id, "");
      setEntries(list);
    })();
  }, []);

  return (
    <div className="file-explorer">
      <h2>Arquivos</h2>
      <label>
        Busca
        <input
          aria-label="Busca no workspace"
          value={props.query}
          onChange={(e) => props.onQuery(e.target.value)}
        />
      </label>
      <ul>
        {entries
          .filter((e) => !props.query || e.name.includes(props.query))
          .map((e) => (
            <li key={e.relativePath}>
              <button type="button" onClick={() => props.onOpen(e.relativePath)}>
                {e.name}
              </button>
            </li>
          ))}
      </ul>
      {!workspaceId && <p>Abrindo workspace…</p>}
    </div>
  );
}
